/*
 * testme-sans-font.js — TestMe Sans per jsPDF (base64, SIL OFL).
 * GENERATO da tools/font/prepara-font.py — non modificare a mano.
 *
 * Perche base64 e non un fetch del .ttf: l app si apre con loadFile, cioe
 * su file://, dove fetch e XHR verso un altro file sono bloccati. Lo stesso
 * motivo per cui spacemono-font.js e fatto cosi.
 * Il modulo si carica A RICHIESTA (MappAIFontCore.caricaPerPdf) — non al boot:
 * sono ~200 KB per famiglia e servono solo a chi esporta un PDF in quel font.
 *
 * window.MappAIFont_testme_sans.registerInto(pdf) → registra normale + bold.
 */
(function () {
  "use strict";
  var NOME = "TestMe Sans";
  var REGULAR = "";
  var BOLD = "";
  function registerInto(pdf) {
    if (!pdf || typeof pdf.addFileToVFS !== "function") return false;
    try {
      pdf.addFileToVFS(NOME + "-Regular.ttf", REGULAR);
      pdf.addFont(NOME + "-Regular.ttf", NOME, "normal");
      pdf.addFileToVFS(NOME + "-Bold.ttf", BOLD);
      pdf.addFont(NOME + "-Bold.ttf", NOME, "bold");
      return true;
    } catch (e) { return false; }
  }
  window.MappAIFont_testme_sans = { fontName: NOME, registerInto: registerInto };
})();
